// components/Chart.tsx
import React, { useRef, useEffect, useState } from "react";
import { Chart as ChartJS, BarElement, CategoryScale, LinearScale, Tooltip, Legend } from "chart.js";
import { Bar } from "react-chartjs-2";
import styles from "./Chart.module.css";

// Additional helper functions for data processing.
function processData(rawData: any[]): number[] {
  return rawData.map(item => item.value);
}

interface ChartProps {
  title: string;
  data: any[];
}

export const Chart = ({ title, data }: ChartProps) => {
  const chartRef = useRef<HTMLCanvasElement>(null);
  const [chartData, setChartData] = useState<number[]>([]);

  useEffect(() => {
    setChartData(processData(data));
    if (chartRef.current) {
      const ctx = chartRef.current.getContext("2d");
      if (ctx) {
        new ChartJS(ctx, {
          type: "bar",
          data: {
            labels: data.map(item => item.label),
            datasets: [{
              label: title,
              data: chartData,
              backgroundColor: "rgba(75,192,192,0.4)",
            }],
          },
          options: {
            responsive: true,
            plugins: {
              legend: { position: "top" },
              tooltip: { enabled: true },
            },
          },
        });
      }
    }
  }, [data, chartData, title]);

  return (
    <div className={styles.chartContainer}>
      <h2>{title}</h2>
      <canvas ref={chartRef} />
    </div>
  );
};

